def walkthrough(slug, title, code):
    import re
    lesson_slug = re.sub(r'[^a-z0-9]+', '-', title.lower()).strip('-')
    custom = EXTRA.get(slug + '/' + lesson_slug)
    if not custom and 'introduction' in {key.rsplit('/', 1)[-1] for key in EXTRA if key.startswith(slug+'/')}:
        # Source introduction titles vary; exact titles below map only their first lessons.
        intro_titles = {'sass':'Set up the Sass tool','less':'Build your first Less file','web-accessibility':'Use a real button','responsive-web-design':'Let the page use the device width','progressive-web-apps':'Start with a useful website','web-performance':'Measure before changing code','vue':'Show a value in a template','svelte':'Show a value','nextjs':'Make the home page','astro':'Make an Astro page','jquery':'Select a page part','react-native':'Make a native screen','electron':'Know the two main sides','d3':'Select and append an SVG shape','redis':'Store a value under a key','firestore':'Meet collections and documents','supabase':'Know the database and the client','elasticsearch':'Meet an index and document','cassandra':'Create a local practice keyspace','neo4j':'Create a node with a label','dynamodb':'Design the item key'}
        if intro_titles.get(slug)==title:
            custom = EXTRA.get(slug+'/introduction')
    if custom:
        return custom
    matches = [(key, note) for key, note in NOTES.items() if key in code]
    # Prefer rare, concept-specific syntax over common setup lines appearing in every example.
    setup = {'SELECT ', 'WHERE ', 'querySelector(', 'PerspectiveCamera', 'MeshBasicMaterial',
             'maintainAspectRatio:false', 'IonContent', 'connectFirestoreEmulator', 'ExpressionAttributeNames',
             'ExpressionAttributeValues', 'ref(', 'useState(', '.subscribe(', 'MATCH '}
    matches.sort(key=lambda pair: pair[0] in setup)
    return [note for _key, note in matches[:3]]
